Here is the commit message:
tcp: Fix Use-After-Free in tcp_ao_connect_init

Since call_rcu, which is called in the hlist_for_each_entry_rcu traversal
of tcp_ao_connect_init, is not part of the RCU read critical section, it
is possible that the RCU grace period will pass during the traversal and
the key will be free.

To prevent this, it should be changed to hlist_for_each_entry_safe.

Fixes: 7c2ffaf21bd6 ("net/tcp: Calculate TCP-AO traffic keys")
Signed-off-by: Hyunwoo Kim <v4bel@theori.io>
Reviewed-by: Eric Dumazet <edumazet@google.com>
Acked-by: Dmitry Safonov <0x7f454c46@gmail.com>
Link: https://lore.kernel.org/r/ZiYu9NJ/ClR8uSkH@v4bel-B760M-AORUS-ELITE-AX
Signed-off-by: Jakub Kicinski <kuba@kernel.org>

Here is the root cause:
The bug arises because the `call_rcu` function, which is invoked during the traversal of the linked list in `tcp_ao_connect_init`, is not part of the RCU read critical section. This can lead to a situation where the RCU grace period expires during the traversal, resulting in the key being freed while still being accessed, causing a use-after-free vulnerability.

Here is the patch:

 void tcp_ao_connect_init(struct sock *sk)
 {
 	struct tcp_sock *tp = tcp_sk(sk);
 	struct tcp_ao_info *ao_info;
+	struct hlist_node *next;
 	union tcp_ao_addr *addr;
 	struct tcp_ao_key *key;
 	int family, l3index;

 	ao_info = rcu_dereference_protected(tp->ao_info,
 					    lockdep_sock_is_held(sk));
 	if (!ao_info)
 		return;

 	/* Remove all keys that don't match the peer */
 	family = sk->sk_family;
 	if (family == AF_INET)
 		addr = (union tcp_ao_addr *)&sk->sk_daddr;
 #if IS_ENABLED(CONFIG_IPV6)
 	else if (family == AF_INET6)
 		addr = (union tcp_ao_addr *)&sk->sk_v6_daddr;
 #endif
 	else
 		return;
 	l3index = l3mdev_master_ifindex_by_index(sock_net(sk),
 						 sk->sk_bound_dev_if);

-	hlist_for_each_entry_rcu(key, &ao_info->head, node) {
+	hlist_for_each_entry_safe(key, next, &ao_info->head, node) {
 		if (!tcp_ao_key_cmp(key, l3index, addr, key->prefixlen, family, -1, -1))
 			continue;

 		if (key == ao_info->current_key)
 			ao_info->current_key = NULL;
 		if (key == ao_info->rnext_key)
 			ao_info->rnext_key = NULL;
 		hlist_del_rcu(&key->node);
 		atomic_sub(tcp_ao_sizeof_key(key), &sk->sk_omem_alloc);
 		call_rcu(&key->rcu, tcp_ao_key_free_rcu);
 	}

 	key = tp->af_specific->ao_lookup(sk, sk, -1, -1);
 	if (key) {
 		/* if current_key or rnext_key were not provided,
 		 * use the first key matching the peer
 		 */
 		if (!ao_info->current_key)
 			ao_info->current_key = key;
 		if (!ao_info->rnext_key)
 			ao_info->rnext_key = key;
 		tp->tcp_header_len += tcp_ao_len_aligned(key);

 		ao_info->lisn = htonl(tp->write_seq);
 		ao_info->snd_sne = 0;
 	} else {
 		/* Can't happen: tcp_connect() verifies that there's
 		 * at least one tcp-ao key that matches the remote peer.
 		 */
 		WARN_ON_ONCE(1);
 		rcu_assign_pointer(tp->ao_info, NULL);
 		kfree(ao_info);
 	}
 }



